# Set up a working tree from a fresh clone.
#
#   .\setup.ps1                # fetch engine + libchdr, apply the project's engine patches, build
#   .\setup.ps1 -SkipBuild     # fetch, patch and install only
#
# You still supply the game: a .gdi dump of Draconus: Cult of the Wyrm (USA, V1.000).
# Nothing from the disc is downloaded, committed or generated by this script.
param(
    [switch]$SkipBuild,
    [string]$Sdl3Dir = ""
)

$ErrorActionPreference = "Stop"
$root = Split-Path -Parent $MyInvocation.MyCommand.Path
$engine = Join-Path $root "engine"
$dl = Join-Path $root "work\dl"

# The engine is pinned to the commit this project was developed against.
$EngineUrl = "https://codeload.github.com/phobos665/dream-recomp/zip/51ca2766d2ebeae9caacda4e305eacb88cf64013"
$EnginePin = "51ca2766d2ebeae9caacda4e305eacb88cf64013"

# libchdr is the engine's only submodule. It is not pinned here; see docs/LEGAL.md.
$LibchdrUrl = "https://codeload.github.com/rtissera/libchdr/zip/refs/heads/master"

function Get-Zip($url, $dest) {
    New-Item -ItemType Directory -Force $dl | Out-Null
    $zip = Join-Path $dl ((Split-Path $dest -Leaf) + ".zip")
    curl.exe -L --fail --silent --show-error -o $zip $url
    $tmp = Join-Path $dl ((Split-Path $dest -Leaf) + "-src")
    if (Test-Path $tmp) { Remove-Item $tmp -Recurse -Force }
    Expand-Archive -LiteralPath $zip -DestinationPath $tmp -Force
    $inner = Get-ChildItem $tmp -Directory | Select-Object -First 1
    New-Item -ItemType Directory -Force $dest | Out-Null
    Copy-Item (Join-Path $inner.FullName "*") $dest -Recurse -Force
}

if (-not (Test-Path (Join-Path $engine "CMakeLists.txt"))) {
    Write-Host "fetching dream-recomp @ $EnginePin"
    Get-Zip $EngineUrl $engine
}
if (-not (Test-Path (Join-Path $engine "third_party\libchdr\CMakeLists.txt"))) {
    Write-Host "fetching libchdr"
    Get-Zip $LibchdrUrl (Join-Path $engine "third_party\libchdr")
}

# Our title configuration lives in this repository, outside the engine, so an engine update
# never overwrites it. Per-game extracted data is not copied: it is the owner's. The disc image
# is the one line setup must not reset: the owner configured it with import-disc, and re-running
# setup after that has to keep it.
foreach ($game in Get-ChildItem (Join-Path $root "game") -Directory) {
    $target = Join-Path $engine "games\$($game.Name)"
    New-Item -ItemType Directory -Force $target | Out-Null
    $targetToml = Join-Path $target "$($game.Name).toml"
    $importedImage = $null
    if (Test-Path $targetToml) {
        $line = Select-String -LiteralPath $targetToml -Pattern '^\s*image\s*=\s*"(.*)"' |
                Select-Object -First 1
        if ($line -and $line.Matches[0].Groups[1].Value -notlike "CHANGE-ME*") {
            $importedImage = $line.Line
        }
    }
    Copy-Item (Join-Path $game.FullName "*.toml") $target -Force
    Copy-Item (Join-Path $game.FullName "CMakeLists.txt") $target -Force
    if ($importedImage) {
        $text = Get-Content $targetToml -Raw
        $text = [regex]::Replace($text, '(?m)^[ \t]*image[ \t]*=.*$',
                                 [System.Text.RegularExpressions.MatchEvaluator] {
                                     param($match) $importedImage
                                 })
        Set-Content -LiteralPath $targetToml -Value $text -NoNewline
        Write-Host "kept imported disc for games\$($game.Name)"
    }
    Write-Host "installed title config: games\$($game.Name)"
}

# The engine is fetched pristine; the project's changes are in patches/ (docs/ENGINE-CHANGES.md).
# Re-running is safe: a patch that is already in the tree is recognised and left alone. The patch
# paths are relative to the repository root, so apply from there with --directory=engine.
Push-Location $root
try {
    foreach ($patch in Get-ChildItem (Join-Path $root "patches") -Filter *.patch -ErrorAction SilentlyContinue |
             Sort-Object Name) {
        & git apply --check --directory=engine $patch.FullName 2>$null
        if ($LASTEXITCODE -eq 0) {
            & git apply --directory=engine $patch.FullName
            if ($LASTEXITCODE -ne 0) { throw "could not apply $($patch.Name)" }
            Write-Host "applied engine patch: $($patch.Name)"
        } else {
            & git apply --reverse --check --directory=engine $patch.FullName 2>$null
            if ($LASTEXITCODE -eq 0) {
                Write-Host "engine patch already applied: $($patch.Name)"
            } else {
                throw ("$($patch.Name) neither applies nor is already applied.`n" +
                       "The engine tree is not the pinned commit plus these patches; " +
                       "see patches/README.md.")
            }
        }
    }
} finally {
    Pop-Location
}

if ($SkipBuild) {
    Write-Host "`nnext: tools\import-disc.bat `"D:\path\to\draconus.gdi`", then re-run .\setup.ps1"
    return
}

# The build translates the extracted boot executable. It is the owner's data and never committed,
# so a fresh clone has to produce it from the disc it imported.
$toml = Join-Path $engine "games\draconus\draconus.toml"
$binary = Join-Path $engine "games\draconus\extracted\fs\1ST_READ.BIN"
if (-not (Test-Path $binary)) {
    $image = $null
    if (Test-Path $toml) {
        $line = Select-String -LiteralPath $toml -Pattern '^\s*image\s*=\s*"(.*)"' | Select-Object -First 1
        if ($line) { $image = $line.Matches[0].Groups[1].Value }
    }
    if ($image -and $image -notlike "CHANGE-ME*" -and (Test-Path -LiteralPath $image)) {
        Write-Host "extracting the boot executable from the configured dump"
        Push-Location (Join-Path $root "tools\draconus-disc")
        try {
            python -m dracdisc extract $image -o (Join-Path $engine "games\draconus\extracted\fs")
            if ($LASTEXITCODE -ne 0) { throw "extraction failed" }
        } finally {
            Pop-Location
        }
    }
}
if (-not (Test-Path $binary)) {
    Write-Host ""
    Write-Host "No extracted boot executable yet, so there is nothing to translate:"
    Write-Host "  1. tools\import-disc.bat `"D:\path\to\draconus.gdi`""
    Write-Host "  2. re-run .\setup.ps1"
    return
}

$vc = "C:\Program Files (x86)\Microsoft Visual Studio\2022\BuildTools\VC\Auxiliary\Build\vcvars64.bat"
if (-not (Test-Path $vc)) { throw "Visual Studio 2022 Build Tools not found: $vc" }

# A local SDL3 build is what this project used; anywhere else, pass -Sdl3Dir or install SDL3.
if (-not $Sdl3Dir) {
    $localSdl = Join-Path $root "work\sdl3\cmake"
    if (Test-Path (Join-Path $localSdl "SDL3Config.cmake")) {
        $Sdl3Dir = $localSdl
    } else {
        Write-Host "note: no SDL3 found under work\sdl3; pass -Sdl3Dir <path>\cmake (docs/09-TOOLING.md)"
    }
}

$cmakeArgs = @(
    "-S", ".", "-B", "build-render", "-G", "Ninja",
    "-DCMAKE_BUILD_TYPE=Release",
    "-DDREAM_DEV_INTERPRETER=ON", "-DDREAM_RENDERER=ON",
    "-DDREAM_BUILD_TESTS=OFF", "-DDREAM_WERROR=OFF"
)
if ($Sdl3Dir) { $cmakeArgs += "-DSDL3_DIR=$Sdl3Dir" }

Push-Location $engine
try {
    cmd /c "`"$vc`" >nul && cmake $($cmakeArgs -join ' ')"
    cmd /c "`"$vc`" >nul && cmake --build build-render --target draconus_boot --parallel"
} finally {
    Pop-Location
}

# SDL3 is a runtime dependency too, and the launcher scripts expect the DLL next to the executable.
$exeDir = Join-Path $engine "build-render\games\draconus"
$dll = Join-Path $exeDir "SDL3.dll"
if ((Test-Path $exeDir) -and -not (Test-Path $dll)) {
    $candidates = @()
    if ($Sdl3Dir) { $candidates += (Join-Path (Split-Path $Sdl3Dir -Parent) "bin\SDL3.dll") }
    $candidates += (Join-Path $root "work\sdl3\bin\SDL3.dll")
    foreach ($candidate in $candidates) {
        if (Test-Path $candidate) {
            Copy-Item $candidate $dll
            Write-Host "copied SDL3.dll next to the executable"
            break
        }
    }
}

Write-Host "`nbuilt: engine\build-render\games\draconus\draconus_boot.exe"
Write-Host "run:   .\play-draconus.bat"
